package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ExpectedEveryMinutesVO;

class ExpectedEveryMinutesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of expected every minutes of observed source")
  void test_expected_every_minutes_value_holder_assign_plain_value() {
    Object holder = new Object();
    ExpectedEveryMinutesValueHolder<Object> value = new ExpectedEveryMinutesValueHolder<>(holder);
    Assertions.assertSame(holder, value.expectedEveryMinutes(1), "Setters must return the holder");
    Assertions.assertTrue(value.getExpectedEveryMinutesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getExpectedEveryMinutes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.expectedEveryMinutesNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getExpectedEveryMinutesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getExpectedEveryMinutes().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of expected every minutes of observed source")
  void test_expected_every_minutes_value_holder_assign_value_object() {
    Object holder = new Object();
    ExpectedEveryMinutesValueHolder<Object> value = new ExpectedEveryMinutesValueHolder<>(holder);
    ExpectedEveryMinutesVO vo = ExpectedEveryMinutesVO.from(1);
    Assertions.assertFalse(value.getExpectedEveryMinutesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.expectedEveryMinutes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getExpectedEveryMinutesValue().orElseThrow());
    Assertions.assertSame(holder, value.expectedEveryMinutes(Optional.empty()));
    Assertions.assertFalse(value.getExpectedEveryMinutesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.expectedEveryMinutes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getExpectedEveryMinutesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of expected every minutes of observed source against the original")
  void test_expected_every_minutes_value_holder_read() {
    Object holder = new Object();
    ExpectedEveryMinutesValueHolder<Object> value = new ExpectedEveryMinutesValueHolder<>(holder);
    ExpectedEveryMinutesVO vo = ExpectedEveryMinutesVO.from(1);
    ExpectedEveryMinutesVO other = ExpectedEveryMinutesVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getExpectedEveryMinutesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readExpectedEveryMinutes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readExpectedEveryMinutes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.expectedEveryMinutes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readExpectedEveryMinutes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readExpectedEveryMinutes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of expected every minutes of observed source")
  void test_expected_every_minutes_value_holder_unset() {
    Object holder = new Object();
    ExpectedEveryMinutesValueHolder<Object> value = new ExpectedEveryMinutesValueHolder<>(holder);
    ExpectedEveryMinutesVO vo = ExpectedEveryMinutesVO.from(1);
    value.expectedEveryMinutes(vo);
    Assertions.assertSame(holder,
        value.unsetExpectedEveryMinutesIfMatches("expectedEveryMinutes_other"));
    Assertions.assertTrue(value.getExpectedEveryMinutesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetExpectedEveryMinutesIfMatches("expectedEveryMinutes"));
    Assertions.assertFalse(value.getExpectedEveryMinutesValue().isPresent(),
        "The field name must clear the value");
    value.expectedEveryMinutes(vo);
    Assertions.assertSame(holder, value.unsetExpectedEveryMinutes());
    Assertions.assertFalse(value.getExpectedEveryMinutesValue().isPresent(),
        "Unset must clear the value");
  }
}
